import re,io
temp=dict(re.findall(r'\b(\w+):\s*"(warm|cool|neutral)"',io.open('/tmp/ct.ts').read()))
RAT={k:int(v) for k,v in re.findall(r'"([a-z]+\|[a-z]+)":\s*(\d)',io.open('/tmp/pr.ts').read())}
NEU=set("black charcoal grey white ivory cream stone sand beige taupe khaki camel tan caramel chocolate brown navy indigo denim olive".split())
def harmony(f):
    a=len({c for c in f if c not in NEU}); return max(0,min(1,1-max(0,a-1)*0.25))
def tempco(items):
    w=co=0
    for it in items:
        ts={temp.get(c) for c in it}
        if 'warm' in ts: w+=1
        if 'cool' in ts: co+=1
    if w+co<2: return None
    return 0.5+0.5*min(1,max(0,(max(w,co)/(w+co)-0.5)/0.2))
def pair(f):
    s=list(dict.fromkeys(f)); r=[]
    for i in range(len(s)):
        for j in range(i+1,len(s)):
            k="|".join(sorted([s[i],s[j]]))
            if k in RAT: r.append(RAT[k])
    return None if not r else (sum(r)/len(r)-1)/4
def echo(items):
    c={}
    for it in items:
