import { readFileSync, writeFileSync } from "node:fs";
import { buildCandidates, type CandidateItem } from "../candidates";
import { temperatureOf } from "../styling/colour-table";
type Row = CandidateItem & { name: string; material: string | null };
const closet = JSON.parse(readFileSync("/tmp/closet.json", "utf8")) as Row[];
const NEW_NEUTRAL = new Set(["black","charcoal","grey","silver","white","stone","denim"]);
const newTemp = (c: string) => (NEW_NEUTRAL.has(c.trim().toLowerCase()) ? "neutral" : temperatureOf(c));

function votes(combo: CandidateItem[], f: (c: string) => string) {
  let warm = 0, cool = 0;
  for (const i of combo) {
    const t = new Set(i.colors.map(f));
    if (t.has("warm")) warm++;
    if (t.has("cool")) cool++;
  }
  return warm + cool;
}
test("probe", () => {
  const c = buildCandidates(closet, { band: [2,4.5], weather:{tempC:18,rain:false}, season:"Autumn", excludeItemIds:[], maxAccessories:2, maxBags:1 } as never);
  const before = c.filter((x) => votes(x, temperatureOf) >= 2).length;
  const after = c.filter((x) => votes(x, newTemp) >= 2).length;
  const out = [`combos=${c.length}`,
    `temperature term FIRES: before=${before} (${Math.round(100*before/c.length)}%)  after=${after} (${Math.round(100*after/c.length)}%)`];
  const counts: Record<string, number> = {};
  for (const i of closet) for (const col of i.colors) counts[`${col}:${temperatureOf(col)}->${newTemp(col)}`] = (counts[`${col}:${temperatureOf(col)}->${newTemp(col)}`] ?? 0) + 1;
  out.push("closet colours: " + Object.entries(counts).map(([k,v])=>`${k}(${v})`).join(", "));
  writeFileSync("/tmp/probe.txt", out.join("\n"));
  expect(true).toBe(true);
});
