import { colorHex } from "@/lib/closet/vocab";

/**
 * Value contrast: whether the outfit's blocks are distinguishable from one
 * another, judged on the hex the palette already carries.
 *
 * ⚠️ **This exists because pairwise colour averaging cannot see a muddy trio.**
 * Every pair in `camel / beige / camel` is individually pleasant, so the colour
 * model scored it 0.9090 — ABOVE `camel / black / black` at 0.8869, which the
 * research endorses, and exactly level with `navy / white / white`, a classic.
 * Nothing in the scorer could tell those three apart.
 *
 * ⚠️ **CONTRAST RATIO, not luminance difference.** The first design used the
 * difference and it does not work: `camel/beige/camel` spans 0.2749 and
 * `camel/black/black` spans 0.2827 — nearly identical, because a difference
 * treats the dark end of the scale as linear when the eye does not. The WCAG
 * ratio `(L1 + 0.05) / (L2 + 0.05)` puts them at 1.81 and 5.96. Measuring is
 * what caught this; the difference-based version would have shipped scoring the
 * trap and the endorsement the same.
 */

/** WCAG relative luminance, 0 (black) .. 1 (white). */
export function relativeLuminance(hex: string): number | null {
  const h = hex.replace("#", "").trim();
  if (!/^[0-9a-fA-F]{6}$/.test(h)) return null;
  const channel = (v: number) => {
    const s = v / 255;
    return s <= 0.03928 ? s / 12.92 : ((s + 0.055) / 1.055) ** 2.4;
  };
  const r = channel(parseInt(h.slice(0, 2), 16));
  const g = channel(parseInt(h.slice(2, 4), 16));
  const b = channel(parseInt(h.slice(4, 6), 16));
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
}

/** WCAG contrast ratio between two luminances, 1 (identical) .. 21 (black/white). */
export function contrastRatio(a: number, b: number): number {
  const [hi, lo] = a >= b ? [a, b] : [b, a];
  return (hi + 0.05) / (lo + 0.05);
}

/**
 * The ratio at which two blocks read as deliberately separated.
 *
 * 3:1 is the WCAG large-text threshold — the standard's own answer to "can a
 * person tell these apart at a glance", which is the same question an outfit
 * asks. Chosen because it is an external landmark rather than a number tuned
 * until the local closet looked right; the `n users` rule forbids the latter.
 */
const CLEAR_SEPARATION = 3;

/**
 * One garment's value, taken from its DARKEST dominant colour.
 *
 * A two-tone garment has no single value, and the darker block is what the eye
 * reads as the shape. Returns null for a garment with no colour the palette
 * knows — hardware, or a colour outside the 42.
 */
function garmentValue(colours: readonly string[]): number | null {
  const lums = colours
    .map((c) => colorHex(c.trim().toLowerCase()))
    .filter((h): h is string => !!h)
    .map(relativeLuminance)
    .filter((l): l is number => l != null);
  return lums.length ? Math.min(...lums) : null;
}

/**
 * How clearly the outfit's garments separate by value, or `null` with nothing
 * to compare.
 *
 * Rises with the strongest contrast present, saturating at `CLEAR_SEPARATION`.
 * Measured on the cases that motivated it:
 *
 *   1.00  all black, all navy      -> 0     (a true tonal column)
 *   1.81  camel / beige / camel    -> 0.40  (the muddy trap)
 *   2.74  white / camel / white    -> 0.87
 *   5.96  camel / black / black    -> 1     (endorsed by the research)
 *  11.88  navy / white / white     -> 1     (a classic)
 *
 * ⚠️ **A score of 0 for a true tonal column is deliberate but INCOMPLETE on its
 * own.** An all-black outfit in one flat weave really is dull; the same outfit
 * in cable knit, twill and suede is not, and telling those apart is what
 * `textureVariety` is for. This term is written to be composed with it, never
 * used alone.
 *
 * ⚠️ Per GARMENT, not per colour token — the shape `temperatureCoherence` and
 * `echoScore` both use. Flattening would let one two-tone shoe manufacture the
 * whole contrast by itself.
 */
export function valueContrast(perItemColours: readonly (readonly string[])[]): number | null {
  const values = perItemColours
    .map(garmentValue)
    .filter((v): v is number => v != null);
  if (values.length < 2) return null;

  let strongest = 1;
  for (let i = 0; i < values.length; i++) {
    for (let j = i + 1; j < values.length; j++) {
      strongest = Math.max(strongest, contrastRatio(values[i], values[j]));
    }
  }
  const reach = (strongest - 1) / (CLEAR_SEPARATION - 1);
  return Math.min(1, Math.max(0, reach));
}

import { relativeLuminance, contrastRatio, valueContrast } from "../value";

test("relative luminance runs black to white", () => {
  expect(relativeLuminance("#000000")).toBeCloseTo(0, 5);
  expect(relativeLuminance("#ffffff")).toBeCloseTo(1, 5);
  expect(relativeLuminance("#141414")).toBeLessThan(0.02); // the palette's black
});

test("a malformed hex is null, not zero — zero would read as pure black", () => {
  expect(relativeLuminance("nope")).toBeNull();
  expect(relativeLuminance("#12345")).toBeNull();
  expect(relativeLuminance("")).toBeNull();
});

test("contrast ratio is symmetric and bottoms out at 1", () => {
  expect(contrastRatio(0.5, 0.5)).toBe(1);
  expect(contrastRatio(0.9, 0.1)).toBeCloseTo(contrastRatio(0.1, 0.9), 10);
  expect(contrastRatio(1, 0)).toBeCloseTo(21, 1);
});

// ---------------------------------------------------------------------------
// The defect this term exists for.
// ---------------------------------------------------------------------------

test("the endorsed trio beats the muddy one", () => {
  // Measured on develop before this term: camel/beige/camel scored 0.9090 and
  // camel/black/black 0.8869 — the trap ABOVE the endorsement.
  const trap = valueContrast([["camel"], ["beige"], ["camel"]])!;
  const endorsed = valueContrast([["camel"], ["black"], ["black"]])!;
  expect(endorsed).toBeGreaterThan(trap);
});

test("a classic separates further than the muddy trio", () => {
  const trap = valueContrast([["camel"], ["beige"], ["camel"]])!;
  expect(valueContrast([["navy"], ["white"], ["white"]])!).toBeGreaterThan(trap);
  expect(valueContrast([["white"], ["navy"], ["brown"]])!).toBeGreaterThan(trap);
});

// ⚠️ Luminance DIFFERENCE cannot do this, which is why the ratio is used. The
// two trios below span 0.2749 and 0.2827 — indistinguishable by difference —
// and 1.81 vs 5.96 by ratio. This test fails against a difference-based
// implementation, which is exactly the version that was nearly written.
test("the ratio, not the span, is what separates them", () => {
  const trap = valueContrast([["camel"], ["beige"], ["camel"]])!;
  const endorsed = valueContrast([["camel"], ["black"], ["black"]])!;
  expect(endorsed - trap).toBeGreaterThan(0.4);
});

test("a true tonal column scores zero — it is rescued by texture, not by colour", () => {
  expect(valueContrast([["black"], ["black"], ["black"]])).toBe(0);
  expect(valueContrast([["navy"], ["navy"], ["navy"]])).toBe(0);
});

test("null with nothing to compare", () => {
  expect(valueContrast([])).toBeNull();
  expect(valueContrast([["navy"]])).toBeNull();
  // A colour outside the palette contributes no value.
  expect(valueContrast([["navy"], ["notacolour"]])).toBeNull();
});

test("a garment is one value, taken from its darkest colour", () => {
  // A two-tone white/navy shoe reads as the navy block, so it contrasts with a
  // white top exactly as a plain navy shoe would — one garment cannot
  // manufacture the whole contrast by itself.
  expect(valueContrast([["white"], ["white", "navy"]])).toBe(
    valueContrast([["white"], ["navy"]]),
  );
});

test("hardware contributes nothing, so a steel watch cannot flatten an outfit", () => {
  // `scoreCombo` passes [] for hardware; that garment must simply not vote.
  expect(valueContrast([["navy"], ["white"], []])).toBe(
    valueContrast([["navy"], ["white"]]),
  );
});

