    if (slot) return { ...slot };
    // Rails are handed out in order and wrap, so a look with more small pieces
    // than rails degrades to overlap rather than to a crash.
    const r = SLOTS[RAILS[rail % RAILS.length]];
    rail += 1;
    return { ...r };
  });
