import { canonicalTrio, TRIO_FAMILIES, KNOWN_FAMILIES } from "../trios";

const look = (top: string, bottom: string, shoes: string) => [
  { category: "Tops", colors: [top] },
  { category: "Bottoms", colors: [bottom] },
  { category: "Shoes", colors: [shoes] },
];

