"use client";

import { useEffect, useState } from "react";
import { CURRENT_RELEASE } from "@/lib/release-notes";
import { WhatsNewCard } from "./whats-new-card";

/**
 * "Here's what changed" — shown once per release, to people who were already here.
 *
 * ⚠️ Mounted on `/generate` rather than in `MobileShell`, for the reason the
 * wear confirmation is: that is the home tab and the screen a returning user
 * lands on, while the shell would fire it mid-capture and mid-edit.
 *
 * ⚠️ The decision is made in an EFFECT, never during render. `localStorage` does
 * not exist on the server, so reading it while rendering would either crash the
 * prerender or hydrate to different markup than the server produced.
 */
const KEY = "fitcheck:last-seen-release";

export function WhatsNew() {
  const [open, setOpen] = useState(false);

  useEffect(() => {
    let seen: string | null;
    try {
      seen = window.localStorage.getItem(KEY);
    } catch {
      // A private window, or site data switched off. Say nothing rather than
      // greeting them on every single load with no way to make it stop.
      return;
    }

    // ⚠️ First run: record the version and show NOTHING. Someone who has never
    // used Fitcheck has nothing to catch up on, and "Fixed: ..." as a first
    // impression reads as an app that was broken.
    if (seen === null) {
      remember();
      return;
    }
    if (seen !== CURRENT_RELEASE.version) setOpen(true);
  }, []);

  function remember() {
    try {
      window.localStorage.setItem(KEY, CURRENT_RELEASE.version);
    } catch {
      // Nothing to do. The worst case is being told the same news twice.
    }
  }

  if (!open) return null;

  return (
    <WhatsNewCard
      release={CURRENT_RELEASE}
      onDismiss={() => {
        setOpen(false);
        remember();
      }}
    />
  );
}
