// Alpha histogram of a stage-0 cutout vs its reference: where does the
// disagreement live, and what alpha does the model assign there?
import { readFileSync } from "node:fs";
import { chromium } from "@playwright/test";
const name = process.argv[2];
const b64 = (p) => readFileSync(p).toString("base64");
const browser = await chromium.launch(); const page = await browser.newPage();
const r = await page.evaluate(async ([ours, ref]) => {
  const px = async (b) => { const bl = await (await fetch("data:image/png;base64," + b)).blob(); const bm = await createImageBitmap(bl); const c = new OffscreenCanvas(bm.width, bm.height); const x = c.getContext("2d"); x.drawImage(bm, 0, 0); return x.getImageData(0, 0, bm.width, bm.height).data; };
  const a = await px(ours), b = await px(ref);
  // pixels the reference says are background (alpha<32) but ours says foreground (alpha>=32)
  const hist = new Array(8).fill(0); let n = 0;
  const histFg = new Array(8).fill(0); let nFg = 0;
  for (let i = 3; i < a.length; i += 4) {
    if (b[i] < 32 && a[i] >= 32) { hist[Math.min(7, a[i] >> 5)]++; n++; }
    if (b[i] >= 224 && a[i] >= 32) { histFg[Math.min(7, a[i] >> 5)]++; nFg++; }
  }
  return { falseFg: n, falseFgAlphaBins: hist.map((v) => (v / n * 100).toFixed(0) + "%"), trueFg: nFg, trueFgAlphaBins: histFg.map((v) => (v / nFg * 100).toFixed(0) + "%") };
}, [b64(`scratch/ours/${name}`), b64(`scratch/baseline/${name}`)]);
